(function(){'use strict';const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const names={IN:'India',US:'United States',GB:'United Kingdom',CA:'Canada',AU:'Australia',AE:'United Arab Emirates',SG:'Singapore',NZ:'New Zealand',DE:'Germany',FR:'France',IE:'Ireland',ZA:'South Africa',ZZ:'Unknown'};const eventNames={library_open:'Library opens',question_open:'Question opens',search_topic:'Search topic signals',search_no_results:'Searches with no match',topic_select:'Topic selections',action_click:'Product interest clicks'};function bars(id,data,question){const el=$(id);if(!Array.isArray(data)||!data.length){el.innerHTML='<p class="empty">No events recorded for this period.</p>';return}const largest=data[0].hits||1;el.innerHTML=data.slice(0,15).map(x=>'<div class="bar-row"><label>'+escape(question?x.title||question.get(x.item)||x.item:names[x.item]||x.item)+'</label><strong>'+Number(x.hits).toLocaleString('en-IN')+'</strong><div class="bar"><i style="width:'+Math.max(3,100*x.hits/largest)+'%"></i></div></div>').join('')}async function load(){const status=$('status');status.textContent='Loading aggregated usage…';try{const r=await fetch('/api/knowledge/admin/summary?days='+$('period').value,{credentials:'same-origin'});if(r.status===401||r.status===403){status.textContent='Operator sign-in is required. Open Administration and sign in.';return}if(!r.ok)throw Error('Storage unavailable or analytics is not configured');const d=await r.json();const qs=new Map();try{const index=window.NavigatorQuestionIndex||{};for(const [key,value] of Object.entries(index))qs.set(key,value)}catch{}$('summary').innerHTML=Object.entries(eventNames).map(([key,label])=>'<div class="metric-card"><span>'+label+'</span><strong>'+Number(d.totals[key]||0).toLocaleString('en-IN')+'</strong></div>').join('');bars('questions',d.questions,qs);bars('searches',d.searchedTopics);bars('topics',d.topics);bars('countries',d.countries);bars('actions',d.actions);status.textContent='Counts since '+d.from+' (UTC); updated on reload. '+d.note;}catch(e){status.textContent='Insights unavailable: '+e.message;}}$('period').addEventListener('change',load);load();})();